if __name__ == "__main__":
    test_vibe()

from fastapi import FastAPI, APIRouter
from fastapi.testclient import TestClient

router = APIRouter()

@router.vibe("/vibe")
def vibe_endpoint():
    return {"message": "vibe check passed"}

app = FastAPI()
app.include_router(router)

client = TestClient(app)

def test_vibe():
    response = client.request("VIBE", "/vibe")
    assert response.status_code == 200
    assert response.json() == {"message": "vibe check passed"}
    print("Vibe check passed!")

if __name__ == "__main__":
    test_vibe()
